package pairing

import (
	"encoding/json"
	"testing"
	"time"
)

// Discovery metadata is attacker controlled until certificate-bound proof passes.
func FuzzVerifyOfferRejectsMalformedDiscovery(f *testing.F) {
	f.Add([]byte(`{"endpoint":"http://example.invalid","salt":"!","nonce":"!","proof":"!"}`))
	f.Add([]byte(`{}`))
	f.Fuzz(func(t *testing.T, raw []byte) {
		if len(raw) > 8192 {
			t.Skip()
		}
		var offer Offer
		if json.Unmarshal(raw, &offer) != nil {
			return
		}
		offer.Expires = time.Now().Add(time.Minute)
		// No offer generated by the fuzzer knows this per-test TLS identity.
		if VerifyOffer("ABCDEFGH", offer, []byte("fuzz-test-certificate")) == nil {
			t.Fatal("untrusted metadata passed certificate proof")
		}
	})
}
